import {hasLiveTask} from './fleet-tasks.js';
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const taskStatusText=r=>r?.task?(r.task.kind==='LINE'?'LINE HARVEST':r.task.kind==='RELAY'?'RELAY OUTPOST':'SURVEY')+' / '+r.task.state+' · '+r.task.stage:'NO AUTONOMOUS JOB';
export function renderFleetTask(record,{enabled=true,blocked=''}={}){
 if(record.task?.kind==='LINE')return '';
 const t=record.task,live=hasLiveTask(record),button=(action,label,disabled=false)=>`<button data-fleet-task="${action}" ${!enabled||disabled?'disabled':''}>${label}</button>`;
 return `<section class="fleetTask" aria-label="Selected aircraft task"><div class="sectionHeading"><span>AUTONOMY / ${esc(record.type.toUpperCase())}</span><b>${t?esc(t.state):'READY'}</b></div><h3>${t?.kind==='RELAY'?'Relay outpost':'Survey ahead & return'}</h3><p>${t?.kind==='RELAY'?'Fly to a fixed outpost, descend, stop rotors and relay the bike’s signal. Radio consumes battery. Recall to recover; low reserve or lost link also triggers return.':t?.relayId?'Wait for the landed relay, survey about 460 m ahead, scan once (3% charge), then return. Terrain, weather and both signal hops limit coverage.':'Fly to a fixed point roughly 70 m ahead of the bike, hold steady for 5 seconds, scan (3% charge), then physically return. No quest items or power are collected.'}</p>${t?`<p class="taskBadge">${esc(taskStatusText(record))}</p><p role="status">${esc(t.reason)}</p>`:''}<div class="taskActions">${button('assign','ASSIGN SURVEY',live)}${live?(t.state==='PAUSED'?button('resume','RESUME JOB'):button('pause','PAUSE / HOLD'))+button('cancel','CANCEL & RETURN'):''}</div><p class="hint">${esc(blocked||'Jobs run only while play is resumed. FPV / HOLD pauses the job; recall cancels it. Safety returns never auto-resume.')}</p>${t?`<details><summary>Task details</summary><dl><dt>Aircraft / battery</dt><dd>${esc(record.id)} / ${esc(record.batteryId)}</dd><dt>Job</dt><dd>${esc(t.id)}</dd><dt>Fixed waypoint (m)</dt><dd>${t.destination.map(n=>n.toFixed(1)).join(' / ')}</dd><dt>Active time / contacts</dt><dd>${Math.floor(t.elapsed)} s / ${t.contacts}</dd></dl></details>`:''}</section>`;
}
